BEGIN;

CREATE TABLE IF NOT EXISTS skolenza."StaffJobFamilyMaster" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NULL,
    "TemplateSourceId" integer NULL,
    "Code" varchar(60) NOT NULL,
    "Name" varchar(150) NOT NULL,
    "Description" varchar(500) NULL,
    "DisplayOrder" smallint NOT NULL DEFAULT 0,
    "IsActive" boolean NOT NULL DEFAULT true,
    "IsSystemDefined" boolean NOT NULL DEFAULT false,
    "AddedById" bigint NULL,
    "AddedDateTime" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedById" bigint NULL,
    "UpdatedDateTime" timestamptz NULL,
    "IsSoftDeleted" boolean NOT NULL DEFAULT false,
    "SoftDeletedById" bigint NULL,
    "DeletedDateTime" timestamptz NULL,
    CONSTRAINT "FK_StaffJobFamilyMaster_Institution" FOREIGN KEY ("InstitutionId") REFERENCES skolenza."Institution"("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_StaffJobFamilyMaster_Template" FOREIGN KEY ("TemplateSourceId") REFERENCES skolenza."StaffJobFamilyMaster"("Id") ON DELETE RESTRICT
);

CREATE UNIQUE INDEX IF NOT EXISTS "UX_StaffJobFamilyMaster_Platform_Code"
    ON skolenza."StaffJobFamilyMaster" (lower("Code"))
    WHERE "InstitutionId" IS NULL AND "IsSoftDeleted" = false;
CREATE UNIQUE INDEX IF NOT EXISTS "UX_StaffJobFamilyMaster_Institution_Code"
    ON skolenza."StaffJobFamilyMaster" ("InstitutionId", lower("Code"))
    WHERE "InstitutionId" IS NOT NULL AND "IsSoftDeleted" = false;
CREATE INDEX IF NOT EXISTS "IX_StaffJobFamilyMaster_TemplateSourceId" ON skolenza."StaffJobFamilyMaster"("TemplateSourceId");

CREATE TABLE IF NOT EXISTS skolenza."StaffCapabilityMaster" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NULL,
    "TemplateSourceId" integer NULL,
    "Code" varchar(60) NOT NULL,
    "Name" varchar(150) NOT NULL,
    "Description" varchar(500) NULL,
    "RequiresCertification" boolean NOT NULL DEFAULT false,
    "CertificationValidityRequired" boolean NOT NULL DEFAULT false,
    "DisplayOrder" smallint NOT NULL DEFAULT 0,
    "IsActive" boolean NOT NULL DEFAULT true,
    "IsSystemDefined" boolean NOT NULL DEFAULT false,
    "AddedById" bigint NULL,
    "AddedDateTime" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedById" bigint NULL,
    "UpdatedDateTime" timestamptz NULL,
    "IsSoftDeleted" boolean NOT NULL DEFAULT false,
    "SoftDeletedById" bigint NULL,
    "DeletedDateTime" timestamptz NULL,
    CONSTRAINT "FK_StaffCapabilityMaster_Institution" FOREIGN KEY ("InstitutionId") REFERENCES skolenza."Institution"("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_StaffCapabilityMaster_Template" FOREIGN KEY ("TemplateSourceId") REFERENCES skolenza."StaffCapabilityMaster"("Id") ON DELETE RESTRICT
);

CREATE UNIQUE INDEX IF NOT EXISTS "UX_StaffCapabilityMaster_Platform_Code"
    ON skolenza."StaffCapabilityMaster" (lower("Code")) WHERE "InstitutionId" IS NULL AND "IsSoftDeleted" = false;
CREATE UNIQUE INDEX IF NOT EXISTS "UX_StaffCapabilityMaster_Institution_Code"
    ON skolenza."StaffCapabilityMaster" ("InstitutionId", lower("Code")) WHERE "InstitutionId" IS NOT NULL AND "IsSoftDeleted" = false;
CREATE INDEX IF NOT EXISTS "IX_StaffCapabilityMaster_TemplateSourceId" ON skolenza."StaffCapabilityMaster"("TemplateSourceId");

CREATE TABLE IF NOT EXISTS skolenza."StaffDutyDefinitionMaster" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
