    CONSTRAINT "FK_StaffDutyDefinitionMaster_Institution" FOREIGN KEY ("InstitutionId") REFERENCES skolenza."Institution"("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_StaffDutyDefinitionMaster_Template" FOREIGN KEY ("TemplateSourceId") REFERENCES skolenza."StaffDutyDefinitionMaster"("Id") ON DELETE RESTRICT
);

CREATE UNIQUE INDEX IF NOT EXISTS "UX_StaffDutyDefinitionMaster_Platform_Code"
    ON skolenza."StaffDutyDefinitionMaster" (lower("Code")) WHERE "InstitutionId" IS NULL AND "IsSoftDeleted" = false;
CREATE UNIQUE INDEX IF NOT EXISTS "UX_StaffDutyDefinitionMaster_Institution_Code"
    ON skolenza."StaffDutyDefinitionMaster" ("InstitutionId", lower("Code")) WHERE "InstitutionId" IS NOT NULL AND "IsSoftDeleted" = false;
CREATE INDEX IF NOT EXISTS "IX_StaffDutyDefinitionMaster_TemplateSourceId" ON skolenza."StaffDutyDefinitionMaster"("TemplateSourceId");

CREATE TABLE IF NOT EXISTS skolenza."StaffPositionMaster" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
