    "DesignationId" integer NULL,
    "Code" varchar(60) NOT NULL,
    "Name" varchar(150) NOT NULL,
    "Description" varchar(500) NULL,
    "DisplayOrder" smallint NOT NULL DEFAULT 0,
    "IsActive" boolean NOT NULL DEFAULT true,
    "IsSystemDefined" boolean NOT NULL DEFAULT false,
    "AddedById" bigint NULL,
    "AddedDateTime" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedById" bigint NULL,
    "UpdatedDateTime" timestamptz NULL,
    "IsSoftDeleted" boolean NOT NULL DEFAULT false,
    "SoftDeletedById" bigint NULL,
    "DeletedDateTime" timestamptz NULL,
    CONSTRAINT "FK_StaffPositionMaster_Institution" FOREIGN KEY ("InstitutionId") REFERENCES skolenza."Institution"("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_StaffPositionMaster_Template" FOREIGN KEY ("TemplateSourceId") REFERENCES skolenza."StaffPositionMaster"("Id") ON DELETE RESTRICT,
