    CONSTRAINT "CK_StaffPositionMaster_PlatformScope" CHECK ("InstitutionId" IS NOT NULL OR ("DepartmentId" IS NULL AND "DesignationId" IS NULL))
);

CREATE UNIQUE INDEX IF NOT EXISTS "UX_StaffPositionMaster_Platform_Code"
    ON skolenza."StaffPositionMaster" (lower("Code")) WHERE "InstitutionId" IS NULL AND "IsSoftDeleted" = false;
CREATE UNIQUE INDEX IF NOT EXISTS "UX_StaffPositionMaster_Institution_Code"
    ON skolenza."StaffPositionMaster" ("InstitutionId", lower("Code")) WHERE "InstitutionId" IS NOT NULL AND "IsSoftDeleted" = false;
CREATE INDEX IF NOT EXISTS "IX_StaffPositionMaster_JobFamily" ON skolenza."StaffPositionMaster"("StaffJobFamilyMasterId");
CREATE INDEX IF NOT EXISTS "IX_StaffPositionMaster_Category" ON skolenza."StaffPositionMaster"("StaffCategoryId");

CREATE TABLE IF NOT EXISTS skolenza."StaffPositionCapability" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
