    CONSTRAINT "FK_StaffPositionDuty_Duty" FOREIGN KEY ("StaffDutyDefinitionMasterId") REFERENCES skolenza."StaffDutyDefinitionMaster"("Id") ON DELETE RESTRICT,
    CONSTRAINT "UX_StaffPositionDuty" UNIQUE ("StaffPositionMasterId", "StaffDutyDefinitionMasterId")
);

CREATE TABLE IF NOT EXISTS skolenza."StaffPositionAssignment" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "StaffMemberId" bigint NOT NULL,
    "StaffPositionMasterId" integer NOT NULL,
    "EffectiveFrom" date NOT NULL,
    "EffectiveTo" date NULL,
    "IsPrimary" boolean NOT NULL DEFAULT false,
    "IsActive" boolean NOT NULL DEFAULT true,
    "Remark" varchar(500) NULL,
    "AddedById" bigint NOT NULL,
    "AddedDateTime" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedById" bigint NULL,
    "UpdatedDateTime" timestamptz NULL,
    CONSTRAINT "FK_StaffPositionAssignment_Institution" FOREIGN KEY ("InstitutionId") REFERENCES skolenza."Institution"("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_StaffPositionAssignment_StaffMember" FOREIGN KEY ("StaffMemberId") REFERENCES skolenza."StaffMember"("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_StaffPositionAssignment_Position" FOREIGN KEY ("StaffPositionMasterId") REFERENCES skolenza."StaffPositionMaster"("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_StaffPositionAssignment_Dates" CHECK ("EffectiveTo" IS NULL OR "EffectiveTo" >= "EffectiveFrom")
);
CREATE INDEX IF NOT EXISTS "IX_StaffPositionAssignment_StaffMember" ON skolenza."StaffPositionAssignment"("InstitutionId", "StaffMemberId", "IsActive");

CREATE OR REPLACE FUNCTION skolenza."ValidatePrimaryStaffPositionAssignment"()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."IsPrimary" AND NEW."IsActive" AND EXISTS (
        SELECT 1 FROM skolenza."StaffPositionAssignment" existing
        WHERE existing."InstitutionId" = NEW."InstitutionId"
          AND existing."StaffMemberId" = NEW."StaffMemberId"
          AND existing."IsPrimary" = true
          AND existing."IsActive" = true
          AND existing."Id" <> COALESCE(NEW."Id", 0)
          AND daterange(existing."EffectiveFrom", COALESCE(existing."EffectiveTo" + 1, 'infinity'::date), '[)') &&
              daterange(NEW."EffectiveFrom", COALESCE(NEW."EffectiveTo" + 1, 'infinity'::date), '[)')
    ) THEN
        RAISE EXCEPTION 'A staff member cannot have overlapping active primary positions.' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS "TR_StaffPositionAssignment_PrimaryOverlap" ON skolenza."StaffPositionAssignment";
CREATE TRIGGER "TR_StaffPositionAssignment_PrimaryOverlap"
BEFORE INSERT OR UPDATE ON skolenza."StaffPositionAssignment"
FOR EACH ROW EXECUTE FUNCTION skolenza."ValidatePrimaryStaffPositionAssignment"();

