    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "StaffMemberId" bigint NOT NULL,
    "StaffCapabilityMasterId" integer NOT NULL,
    "SourcePositionAssignmentId" bigint NULL,
    "VerificationStatus" smallint NOT NULL DEFAULT 1,
    "IsRequired" boolean NOT NULL DEFAULT true,
    "EffectiveFrom" date NOT NULL,
    "EffectiveTo" date NULL,
    "VerifiedById" bigint NULL,
    "VerifiedDateTime" timestamptz NULL,
    "VerificationRemark" varchar(500) NULL,
    "AddedById" bigint NOT NULL,
    "AddedDateTime" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedById" bigint NULL,
    "UpdatedDateTime" timestamptz NULL,
    CONSTRAINT "FK_StaffCapabilityAssignment_Institution" FOREIGN KEY ("InstitutionId") REFERENCES skolenza."Institution"("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_StaffCapabilityAssignment_StaffMember" FOREIGN KEY ("StaffMemberId") REFERENCES skolenza."StaffMember"("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_StaffCapabilityAssignment_Capability" FOREIGN KEY ("StaffCapabilityMasterId") REFERENCES skolenza."StaffCapabilityMaster"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StaffCapabilityAssignment_PositionAssignment" FOREIGN KEY ("SourcePositionAssignmentId") REFERENCES skolenza."StaffPositionAssignment"("Id") ON DELETE CASCADE,
    CONSTRAINT "CK_StaffCapabilityAssignment_Status" CHECK ("VerificationStatus" IN (1, 2, 3)),
    CONSTRAINT "CK_StaffCapabilityAssignment_Dates" CHECK ("EffectiveTo" IS NULL OR "EffectiveTo" >= "EffectiveFrom"),
    CONSTRAINT "UX_StaffCapabilityAssignment" UNIQUE ("StaffMemberId", "StaffCapabilityMasterId", "EffectiveFrom")
);

