    CONSTRAINT "FK_StaffDutyAssignment_Duty" FOREIGN KEY ("StaffDutyDefinitionMasterId") REFERENCES skolenza."StaffDutyDefinitionMaster"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StaffDutyAssignment_PositionAssignment" FOREIGN KEY ("SourcePositionAssignmentId") REFERENCES skolenza."StaffPositionAssignment"("Id") ON DELETE CASCADE,
    CONSTRAINT "CK_StaffDutyAssignment_Dates" CHECK ("EffectiveTo" IS NULL OR "EffectiveTo" >= "EffectiveFrom"),
    CONSTRAINT "UX_StaffDutyAssignment" UNIQUE ("StaffMemberId", "StaffDutyDefinitionMasterId", "EffectiveFrom")
);

