FROM (VALUES
 ('INSTITUTION_ADMINISTRATOR','Institution Administrator','Institution leadership and administration.',1::smallint,'ADMINISTRATION',10::smallint),
 ('TEACHER','Teacher','General teaching position; class and subject allocation is managed separately.',2::smallint,'ACADEMICS',20::smallint),
 ('ACCOUNTANT','Accountant','Institution accounting and reconciliation.',3::smallint,'FINANCE_ACCOUNTS',30::smallint),
 ('ELECTRICIAN','Electrician','Electrical maintenance and safety support.',3::smallint,'FACILITIES_MAINTENANCE',40::smallint),
