) AS values("Code","Name","Description","CategoryId","FamilyCode","DisplayOrder")
JOIN skolenza."StaffJobFamilyMaster" family ON family."InstitutionId" IS NULL AND family."Code" = values."FamilyCode"
ON CONFLICT DO NOTHING;

