INSERT INTO skolenza."StaffPositionDuty" ("InstitutionId", "StaffPositionMasterId", "StaffDutyDefinitionMasterId", "IsMandatory", "DisplayOrder")
SELECT NULL, position."Id", duty."Id", true, mapping."DisplayOrder"
FROM (VALUES
 ('TEACHER','PREPARE_LESSON_PLANS',10::smallint),('TEACHER','DELIVER_ASSIGNED_CLASSES',20::smallint),('TEACHER','RECORD_ATTENDANCE',30::smallint),('TEACHER','EVALUATE_STUDENT_WORK',40::smallint),('TEACHER','UPDATE_SYLLABUS_PROGRESS',50::smallint),
 ('INSTITUTION_ADMINISTRATOR','ADMINISTER_INSTITUTION',10::smallint),('ACCOUNTANT','RECONCILE_ACCOUNTS',10::smallint),
 ('ELECTRICIAN','RESOLVE_ELECTRICAL_REQUESTS',10::smallint),('OFFICE_ATTENDANT','INTERNAL_DOCUMENT_DISPATCH',10::smallint),('OFFICE_ATTENDANT','PREPARE_COMMON_AREAS',20::smallint)
