CREATE OR REPLACE FUNCTION skolenza."SeedInstitutionStaffProfessionalMasters"(p_institution_id bigint, p_actor_staff_member_id bigint DEFAULT NULL)
RETURNS void LANGUAGE plpgsql AS $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM skolenza."Institution" WHERE "Id" = p_institution_id) THEN
        RAISE EXCEPTION 'Institution % does not exist.', p_institution_id USING ERRCODE = '23503';
    END IF;

    INSERT INTO skolenza."StaffJobFamilyMaster" ("InstitutionId","TemplateSourceId","Code","Name","Description","DisplayOrder","IsActive","IsSystemDefined","AddedById")
    SELECT p_institution_id,t."Id",t."Code",t."Name",t."Description",t."DisplayOrder",true,false,p_actor_staff_member_id
    FROM skolenza."StaffJobFamilyMaster" t WHERE t."InstitutionId" IS NULL AND t."IsActive" AND NOT t."IsSoftDeleted"
    ON CONFLICT DO NOTHING;

    INSERT INTO skolenza."StaffCapabilityMaster" ("InstitutionId","TemplateSourceId","Code","Name","Description","RequiresCertification","CertificationValidityRequired","DisplayOrder","IsActive","IsSystemDefined","AddedById")
    SELECT p_institution_id,t."Id",t."Code",t."Name",t."Description",t."RequiresCertification",t."CertificationValidityRequired",t."DisplayOrder",true,false,p_actor_staff_member_id
    FROM skolenza."StaffCapabilityMaster" t WHERE t."InstitutionId" IS NULL AND t."IsActive" AND NOT t."IsSoftDeleted"
    ON CONFLICT DO NOTHING;

    INSERT INTO skolenza."StaffDutyDefinitionMaster" ("InstitutionId","TemplateSourceId","Code","Name","Description","DefaultFrequency","RequiresEvidence","DisplayOrder","IsActive","IsSystemDefined","AddedById")
    SELECT p_institution_id,t."Id",t."Code",t."Name",t."Description",t."DefaultFrequency",t."RequiresEvidence",t."DisplayOrder",true,false,p_actor_staff_member_id
    FROM skolenza."StaffDutyDefinitionMaster" t WHERE t."InstitutionId" IS NULL AND t."IsActive" AND NOT t."IsSoftDeleted"
    ON CONFLICT DO NOTHING;

    INSERT INTO skolenza."StaffPositionMaster" ("InstitutionId","TemplateSourceId","StaffJobFamilyMasterId","StaffCategoryId","Code","Name","Description","DisplayOrder","IsActive","IsSystemDefined","AddedById")
    SELECT p_institution_id,p."Id",familyCopy."Id",p."StaffCategoryId",p."Code",p."Name",p."Description",p."DisplayOrder",true,false,p_actor_staff_member_id
    FROM skolenza."StaffPositionMaster" p
    JOIN skolenza."StaffJobFamilyMaster" familyTemplate ON familyTemplate."Id" = p."StaffJobFamilyMasterId"
    JOIN skolenza."StaffJobFamilyMaster" familyCopy ON familyCopy."InstitutionId" = p_institution_id AND familyCopy."TemplateSourceId" = familyTemplate."Id" AND NOT familyCopy."IsSoftDeleted"
    WHERE p."InstitutionId" IS NULL AND p."IsActive" AND NOT p."IsSoftDeleted"
    ON CONFLICT DO NOTHING;

    INSERT INTO skolenza."StaffPositionCapability" ("InstitutionId","StaffPositionMasterId","StaffCapabilityMasterId","IsMandatory","DisplayOrder","AddedById")
    SELECT p_institution_id,positionCopy."Id",capabilityCopy."Id",mapping."IsMandatory",mapping."DisplayOrder",p_actor_staff_member_id
    FROM skolenza."StaffPositionCapability" mapping
    JOIN skolenza."StaffPositionMaster" positionTemplate ON positionTemplate."Id" = mapping."StaffPositionMasterId" AND positionTemplate."InstitutionId" IS NULL
    JOIN skolenza."StaffCapabilityMaster" capabilityTemplate ON capabilityTemplate."Id" = mapping."StaffCapabilityMasterId" AND capabilityTemplate."InstitutionId" IS NULL
    JOIN skolenza."StaffPositionMaster" positionCopy ON positionCopy."InstitutionId" = p_institution_id AND positionCopy."TemplateSourceId" = positionTemplate."Id"
    JOIN skolenza."StaffCapabilityMaster" capabilityCopy ON capabilityCopy."InstitutionId" = p_institution_id AND capabilityCopy."TemplateSourceId" = capabilityTemplate."Id"
    ON CONFLICT DO NOTHING;

    INSERT INTO skolenza."StaffPositionDuty" ("InstitutionId","StaffPositionMasterId","StaffDutyDefinitionMasterId","IsMandatory","DisplayOrder","AddedById")
    SELECT p_institution_id,positionCopy."Id",dutyCopy."Id",mapping."IsMandatory",mapping."DisplayOrder",p_actor_staff_member_id
    FROM skolenza."StaffPositionDuty" mapping
    JOIN skolenza."StaffPositionMaster" positionTemplate ON positionTemplate."Id" = mapping."StaffPositionMasterId" AND positionTemplate."InstitutionId" IS NULL
    JOIN skolenza."StaffDutyDefinitionMaster" dutyTemplate ON dutyTemplate."Id" = mapping."StaffDutyDefinitionMasterId" AND dutyTemplate."InstitutionId" IS NULL
    JOIN skolenza."StaffPositionMaster" positionCopy ON positionCopy."InstitutionId" = p_institution_id AND positionCopy."TemplateSourceId" = positionTemplate."Id"
    JOIN skolenza."StaffDutyDefinitionMaster" dutyCopy ON dutyCopy."InstitutionId" = p_institution_id AND dutyCopy."TemplateSourceId" = dutyTemplate."Id"
    ON CONFLICT DO NOTHING;
END;
$$;

DO $$ DECLARE institution_row record; BEGIN
    FOR institution_row IN SELECT "Id" FROM skolenza."Institution" LOOP
        PERFORM skolenza."SeedInstitutionStaffProfessionalMasters"(institution_row."Id", NULL);
    END LOOP;
END $$;

COMMIT;
